import functools
@functools.lru_cache(maxsize=None)
def gene_at(chrom,pos):
    try:
        r=json.loads(get(f"https://api.genome.ucsc.edu/getData/track?genome=hg38;track=ncbiRefSeqCurated;chrom={chrom};start={pos};end={pos+23}"))
        v=r.get('ncbiRefSeqCurated',[])
        if not isinstance(v,list) or not v: return ("intergenic",False)
        names=set(); exonic=False
        for t in v:
            names.add(t.get('name2') or t.get('name'))
            bs=[int(x) for x in t['exonStarts'].rstrip(',').split(',')]
            be=[int(x) for x in t['exonEnds'].rstrip(',').split(',')]
            for a,b in zip(bs,be):
                if a<=pos+11<=b: exonic=True
        return (",".join(sorted(n for n in names if n)), exonic)
    except Exception as e: return ("ERR:"+type(e).__name__,False)

def mmpos(guide,chrom,pos,strand):
    s=seq(chrom,pos,pos+23)
    if strand=='-': s=rc(s)
    return [i+1 for i in range(20) if s[i]!=guide[i]], s

