        if len(mm)<=3: sub.append((o,mm,s))
        time.sleep(0.05)
    g['sub']=sub
    print(f"\n=== {g['id']} {g['guideSeq']}|{g['pam']}  MIT={g['mit']} Doench2016={g['d16']}  bins(0/1/2/3/4mm)={g['bins']}")
